  ".github/workflows/validate.yml": "# CI for your PRIVATE vault repo (created by `hippo init` or the hosted app).\n# - validate: checks that each push or pull request leaves the vault loadable. Pushes that only add\n#   inbox memories skip it, and so do the app's own commits (they carry [skip ci]).\n# - audit: once a day, reviews the last day's commits, the app's included, and flags any that break\n#   the vault's rules (see AGENTS.md).\n# Curation (\"sleep\") doesn't run here: your own agent does it through the Hippocampus MCP server.\nname: validate\non:\n  push:\n    paths-ignore: [\"inbox/**\"]\n  pull_request:\n    paths-ignore: [\"inbox/**\"]\n  schedule:\n    - cron: \"17 4 * * *\"\n  workflow_dispatch:\n\njobs:\n  validate:\n    if: github.event_name == 'push' || github.event_name == 'pull_request'\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 24\n      # Pin the major version you've tested; bump it deliberately and run `hippo migrate`.\n      - run: npx -y @mehrad77/hippocampus@0 validate\n\n  audit:\n    if: github.event_name == 'schedule' || github.event_name == 'workflow_dispatch'\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 24\n      # A little overlap with the previous run, since scheduled runs can start late.\n      - run: npx -y @mehrad77/hippocampus@0 audit --since \"26 hours ago\"\n",
  ".gitignore": ".obsidian/workspace*.json\n.obsidian/cache\n.trash/\n.DS_Store\n",
